(84,1051,'inc/User_Reg.ASP',6,'<p><b>继续注册前请先阅读论坛协议</b><br>\r\n<br>\r\n欢迎您加入本站点，本站点为公共论坛，请您自觉遵守以下条款：<br>\r\n<br>\r\n<font color=blue>不得利用本站制作，复制和传播下列信息：</font><br>\r\n<br>\r\n(一)煽动抗拒，破坏宪法和法律，行政法规实施的；<br>\r\n(二)煽动颠覆国家政权，推翻社会主义制度的；<br>\r\n(三)煽动分裂国家，破坏国家统一的；<br>\r\n(四)煽动民族仇恨，民族歧视，破坏民族团结的；<br>\r\n(五)捏造或者歪曲事实，散布谣言，扰乱社会秩序的；<br>\r\n(六)宣扬封建迷信，淫秽，色情，赌博，暴力，凶杀，恐怖，教唆犯罪的；<br>\r\n(七)公然侮辱他人或者捏造事实诽谤他人的，或者进行其他恶意攻击的；<br>\r\n(八)损害国家机关信誉的；<br>\r\n(九)其他违反宪法和法律行政法规的；<br>\r\n(十)进行商业广告行为的。<br>\r\n<br>\r\n您只有无条件接受以上所有服务条款，才能继续申请<br>\r\n</P>'),
(85,1051,'inc/Ubbcode_Setup.asp',1,'<%\r\nconst FiltrateBadWordString=\"fuck|傻B|法轮\"\r\nconst DEF_MaxUBBNumber = 10\r\nconst DEF_UbbUnderwriteImages = 1\r\nconst DEF_UbbDefaultEdit = 1\r\nDim DEF_UbbIconG,DEF_UbbIconMax,DEF_UbbIconMin,DEF_UbbIconGNum\r\nDEF_UbbIconGNum = 3\r\nDEF_UbbIconG = Array(\"经典表情\",\"经典表情(大)\",\"蘑菇点点\")\r\nDEF_UbbIconMin = Array(1,47,62)\r\nDEF_UbbIconMax = Array(46,61,99)\r\nDim DEF_UbbLinkData,DEF_UbbLinkUrl,DEF_UbbLinkNum\r\nDEF_UbbLinkNum = 0\r\n\r\n\r\nconst DEF_SafeUrl=\"|leadbbs.com|53520.com|wensui.com|youtube.com|youku.com|weplay.cn|tudou.com|56.com|microsoft.com|baidu.com|xiami.com|sina.com.cn|\"\r\n%>\r\n'),
(86,1051,'inc/Upload_Setup.ASP',3,'<%\r\nconst DEF_BBS_UploadPhotoUrl=\"images/upload/\"\r\nconst DEF_EnableDotNetUpload = 2\r\nconst DEF_UploadFileType=\":.jpg:.gif:.jpeg:.jpe:.zip:.rar:.torrent:.mp3:.swf:.png:.ogg:\"\r\nConst DEF_FileMaxBytes = 8024000\r\nConst DEF_FaceMaxBytes = 1024000\r\nConst DEF_UploadSpendPoints = 0\r\nConst DEF_UploadDeletePoints = 0\r\nConst DEF_UploadOneDayMaxNum = 99\r\nConst DEF_UploadFaceNeedPoints = 0\r\nconst DEF_UploadVersionString=\"\"\r\nconst DEF_Upd_SpendFlag = 0\r\nconst DEF_UploadOnceNum = 10\r\nconst DEF_UploadSwidth = 140\r\nconst DEF_UploadSheight = 105\r\n%>\r\n'),
