-- Uploaded avatars are NOT part of this fixture: the image files live outside the repository,
-- so any row kept here would point at a file a fresh checkout does not have -- a broken avatar
-- beside that user's posts and a 404 in the link crawl (07-links). Users fall back to the
-- system avatars under images/face/, which are shipped.
DELETE FROM leadbbs_userface;
-- Same reasoning for attachments: the files are not in the repository, so the rows would
-- leave broken thumbnails on the board list and 404s in the crawl. The UBB tags that point
-- at them are stripped from the posts as well. Suites that need an attachment upload one.
DELETE FROM leadbbs_upload;
-- ...and the topic image previews that point at those same files (leadbbs_extend holds
-- "2026/07/26_011640s.jpg:2026/07/26_011640.png" style pairs, rendered as lazy-loaded
-- thumbnails on the board list).
DELETE FROM leadbbs_extend
 WHERE ClassType = 200 AND extent_content REGEXP '[0-9]{4}/[0-9]{2}/[0-9]{2}_[0-9]+';
UPDATE leadbbs_announce
   SET Content = REGEXP_REPLACE(Content, '\\[upload=[0-9]+,[0-9]+\\][^\\[]*\\[/upload\\]', '')
 WHERE Content LIKE '%[upload=%';
UPDATE leadbbs_user SET FaceUrl='' WHERE FaceUrl LIKE '%upload%';
SET FOREIGN_KEY_CHECKS=1; SET UNIQUE_CHECKS=1;

-- --- fixture realism ------------------------------------------------------------------------
-- Two ways this dump differed from what the installer actually produces. Each one let a real bug
-- through a green suite, so they are corrected here rather than worked around in the tests.
--
-- 1. `install/database/mysql.sql` adds this column to LeadBBS_user; this dump predates it.
--    Without it, User/LookUserInfo.asp's online-member query selects `T2.remark`, MySQL raises
--    "Unknown column", the page quietly falls through to 用户不存在 — and the feature is
--    untestable while looking merely empty instead of broken.
ALTER TABLE leadbbs_user
  ADD COLUMN `remark` longtext CHARACTER SET utf8 COLLATE utf8_general_ci AFTER `AnnounceNum2`;

-- 2. leadbbs_onlineuser is ephemeral session state — this dump captured whoever happened to be
--    browsing when it was taken, as rows 1, 2, 3 with long-dead session ids. Those rows are not
--    just noise: LeadBBS *updates* an existing row for a returning user instead of inserting, so
--    the seeded row 1 for `admin` pins that account's online id at 1 forever. Clear them, then
--    start the counter where a real forum's is. The ids matter because §46 (values rendered as
--    2.361371e+06) only bites past a million: while a fixture minutes old hands out two-digit
--    ids, no test could ever reach the failing range — which is exactly how that bug reached
--    production. `02-user` asserts the ids really are seven digits, so if this is ever lost the
--    suite says so instead of passing quietly.
DELETE FROM leadbbs_onlineuser;
ALTER TABLE leadbbs_onlineuser AUTO_INCREMENT = 2361371;
